import 'package:flutter/material.dart';import 'package:sehatak/core/services/women_service.dart';class WomenTipsScreen extends StatelessWidget{const WomenTipsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('نصائح صحة المرأة')),body:StreamBuilder(stream:WomenService().streamTips(limit:30),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:s.data!.map((d)=>Card(child:ExpansionTile(leading:const Icon(Icons.lightbulb_outline,color:Color(0xFF9C27B0)),title:Text(d.title),subtitle:Text(d.category),children:[Padding(padding:const EdgeInsets.all(16),child:Text(d.body))]))).toList());}));}}
